export function transcribeDna(dna) {
    const map = { G: 'C', C: 'G', T: 'A', A: 'U' };
    let result = '';
    for (const c of dna) {
        if (!(c in map))
            throw new Error('Invalid DNA nucleotide');
        result += map[c];
    }
    return result;
}
